package com.company.platform.integration.framework;import org.springframework.stereotype.Component;@Component public class DefaultPayloadTransformer implements PayloadTransformer{private final VersionResolver versions;public DefaultPayloadTransformer(VersionResolver v){versions=v;}public Object transform(Object source,String type,String version){if(!versions.compatible(version,versions.resolve(version)))throw new IllegalArgumentException("unsupported payload version");return source;}}
